import { SearchOutlined } from '@ant-design/icons';
import { PageContainer, ProTable } from '@ant-design/pro-components';
import { history } from '@umijs/max';
import { Avatar, Button, DatePicker, Select, Space, Tabs, Typography } from 'antd';
import dayjs from 'dayjs';
import { useEffect, useMemo, useRef, useState } from 'react';
import type { ActionType, ProColumns } from '@ant-design/pro-components';
import {
  getChannelDaily,
  getChannelSummary,
  getChannels,
  getProductSummary,
  getRegionDaily,
  getRegionSummary,
  getRegions,
} from '@/services/api';
import { renderMetricTitle } from '@/utils/metrics';

const { RangePicker } = DatePicker;

type TabKey = 'products' | 'channel' | 'region';
type SummaryDimension = 'channel' | 'region';

type SummaryRow = {
  dimension?: { id?: number; name?: string };
  impressions?: number;
  clicks?: number;
  ctr?: number;
  downloads?: number;
  cvr?: number;
  spend?: number;
  revenue?: number;
  payingUsers?: number;
  registrations?: number;
  roas?: number;
  cpi?: number;
  costPerRegistration?: number;
  costPerPayingUser?: number;
  registrationRate?: number;
  payRate?: number;
  retentionD1Rate?: number;
  retentionD7Rate?: number;
};

const buildSummaryColumns = (dimension: SummaryDimension, onClick: (row: SummaryRow) => void): ProColumns<SummaryRow>[] => {
  const title = dimension === 'channel' ? '渠道' : '推广地区';
  return [
    {
      title,
      dataIndex: ['dimension', 'name'],
      width: 180,
      fixed: 'left',
      render: (_, row) => (
        <a onClick={() => onClick(row)}>{row.dimension?.name || '-'}</a>
      ),
    },
    { title: renderMetricTitle('impressions'), dataIndex: 'impressions', width: 100 },
    { title: renderMetricTitle('clicks'), dataIndex: 'clicks', width: 100 },
    { title: renderMetricTitle('ctr'), dataIndex: 'ctr', width: 90 },
    { title: renderMetricTitle('downloads'), dataIndex: 'downloads', width: 100 },
    { title: renderMetricTitle('cvr'), dataIndex: 'cvr', width: 90 },
    { title: renderMetricTitle('spend'), dataIndex: 'spend', width: 100 },
    { title: renderMetricTitle('revenue'), dataIndex: 'revenue', width: 100 },
    { title: renderMetricTitle('payingUsers'), dataIndex: 'payingUsers', width: 100 },
    { title: renderMetricTitle('registrations'), dataIndex: 'registrations', width: 100 },
    { title: renderMetricTitle('roas'), dataIndex: 'roas', width: 90 },
    { title: renderMetricTitle('cpi'), dataIndex: 'cpi', width: 90 },
    { title: renderMetricTitle('costPerRegistration'), dataIndex: 'costPerRegistration', width: 110 },
    { title: renderMetricTitle('costPerPayingUser'), dataIndex: 'costPerPayingUser', width: 110 },
    { title: renderMetricTitle('registrationRate'), dataIndex: 'registrationRate', width: 100 },
    { title: renderMetricTitle('payRate'), dataIndex: 'payRate', width: 100 },
    { title: renderMetricTitle('retentionD1Rate'), dataIndex: 'retentionD1Rate', width: 100 },
    { title: renderMetricTitle('retentionD7Rate'), dataIndex: 'retentionD7Rate', width: 110 },
  ];
};

const buildDailyColumns = (dimension: SummaryDimension): ProColumns<any>[] => {
  const title = dimension === 'channel' ? '渠道' : '推广地区';
  return [
    { title: '日期', dataIndex: 'date', width: 110, fixed: 'left' },
    { title, dataIndex: [dimension, 'name'], width: 140, fixed: 'left' },
    { title: renderMetricTitle('impressions'), dataIndex: 'impressions', width: 100 },
    { title: renderMetricTitle('clicks'), dataIndex: 'clicks', width: 100 },
    { title: renderMetricTitle('ctr'), dataIndex: 'ctr', width: 90 },
    { title: renderMetricTitle('downloads'), dataIndex: 'downloads', width: 100 },
    { title: renderMetricTitle('cvr'), dataIndex: 'cvr', width: 90 },
    { title: renderMetricTitle('spend'), dataIndex: 'spend', width: 100 },
    { title: renderMetricTitle('revenue'), dataIndex: 'revenue', width: 100 },
    { title: renderMetricTitle('payingUsers'), dataIndex: 'payingUsers', width: 100 },
    { title: renderMetricTitle('registrations'), dataIndex: 'registrations', width: 100 },
    { title: renderMetricTitle('roas'), dataIndex: 'roas', width: 90 },
    { title: renderMetricTitle('cpi'), dataIndex: 'cpi', width: 90 },
    { title: renderMetricTitle('costPerRegistration'), dataIndex: 'costPerRegistration', width: 110 },
    { title: renderMetricTitle('costPerPayingUser'), dataIndex: 'costPerPayingUser', width: 110 },
    { title: renderMetricTitle('registrationRate'), dataIndex: 'registrationRate', width: 100 },
    { title: renderMetricTitle('payRate'), dataIndex: 'payRate', width: 100 },
    { title: renderMetricTitle('retentionD1Rate'), dataIndex: 'retentionD1Rate', width: 100 },
    { title: renderMetricTitle('retentionD7Rate'), dataIndex: 'retentionD7Rate', width: 110 },
  ];
};

const productSummaryColumns: ProColumns<any>[] = [
  {
    title: '图标',
    dataIndex: ['product', 'storeIcon'],
    width: 72,
    fixed: 'left',
    search: false,
    render: (_, row) => (
      <Avatar shape="square" src={row.product?.storeIcon}>
        {row.product?.appName?.[0]}
      </Avatar>
    ),
  },
  {
    title: '名称',
    dataIndex: ['product', 'appName'],
    width: 180,
    fixed: 'left',
    search: false,
    render: (text, row) => (
      <a onClick={() => history.push(`/reports/products/${row.product?.id}`)}>
        {text || row.product?.appId}
      </a>
    ),
  },
  { title: '渠道', dataIndex: ['channel', 'name'], width: 140, search: false },
  { title: '地区', dataIndex: ['region', 'name'], width: 120, search: false },
  { title: '平台', dataIndex: ['product', 'platform'], width: 100, search: false },
  { title: renderMetricTitle('impressions'), dataIndex: 'impressions', width: 100, search: false },
  { title: renderMetricTitle('clicks'), dataIndex: 'clicks', width: 100, search: false },
  { title: renderMetricTitle('ctr'), dataIndex: 'ctr', width: 90, search: false },
  { title: renderMetricTitle('downloads'), dataIndex: 'downloads', width: 100, search: false },
  { title: renderMetricTitle('cvr'), dataIndex: 'cvr', width: 90, search: false },
