  { title: renderMetricTitle('roas'), dataIndex: 'roas', width: 90, search: false },
  { title: renderMetricTitle('cpi'), dataIndex: 'cpi', width: 90, search: false },
  { title: renderMetricTitle('costPerRegistration'), dataIndex: 'costPerRegistration', width: 110, search: false },
  { title: renderMetricTitle('costPerPayingUser'), dataIndex: 'costPerPayingUser', width: 110, search: false },
  { title: renderMetricTitle('registrationRate'), dataIndex: 'registrationRate', width: 100, search: false },
  { title: renderMetricTitle('payRate'), dataIndex: 'payRate', width: 100, search: false },
