    { title: renderMetricTitle('clicks'), dataIndex: 'clicks', width: 100 },
    { title: renderMetricTitle('ctr'), dataIndex: 'ctr', width: 90 },
    { title: renderMetricTitle('downloads'), dataIndex: 'downloads', width: 100 },
    { title: renderMetricTitle('cvr'), dataIndex: 'cvr', width: 90 },
    { title: renderMetricTitle('spend'), dataIndex: 'spend', width: 100 },
    { title: renderMetricTitle('revenue'), dataIndex: 'revenue', width: 100 },
    { title: renderMetricTitle('payingUsers'), dataIndex: 'payingUsers', width: 100 },
    { title: renderMetricTitle('registrations'), dataIndex: 'registrations', width: 100 },
    { title: renderMetricTitle('roas'), dataIndex: 'roas', width: 90 },
    { title: renderMetricTitle('cpi'), dataIndex: 'cpi', width: 90 },
    { title: renderMetricTitle('costPerRegistration'), dataIndex: 'costPerRegistration', width: 110 },
    { title: renderMetricTitle('costPerPayingUser'), dataIndex: 'costPerPayingUser', width: 110 },
    { title: renderMetricTitle('registrationRate'), dataIndex: 'registrationRate', width: 100 },
    { title: renderMetricTitle('payRate'), dataIndex: 'payRate', width: 100 },
    { title: renderMetricTitle('retentionD1Rate'), dataIndex: 'retentionD1Rate', width: 100 },
    { title: renderMetricTitle('retentionD7Rate'), dataIndex: 'retentionD7Rate', width: 110 },
